async function fetchUser(id) {
  try {
    const res = await fetch(`https://api.example.com/users/${id}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const user = await res.json();
    console.log(user.name);
    return user;
  } catch (err) {
    console.error('요청 실패:', err.message);
  }
}

fetchUser(1);
